<?php
namespace App\Filament\Admin\Resources\ClaimPayments\Pages;use App\Application\Claims\ClaimPaymentService;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\ClaimPayments\ClaimPaymentResource;use Filament\Actions\Action;use Filament\Forms\Components\Textarea;use App\Filament\Shared\Pages\RecordDetailPage;final class ViewClaimPayment extends RecordDetailPage{protected static string$resource=ClaimPaymentResource::class;protected function getHeaderActions():array{return[Action::make('approve')->icon('lucide-circle-check')->color('success')->requiresConfirmation()->visible(fn()=>$this->record->status==='PENDING_APPROVAL')->action(function(){if(ServiceValidation::run(fn()=>app(ClaimPaymentService::class)->approve($this->record,auth()->user()))===null)return;}),Action::make('reverse')->icon('lucide-undo-2')->color('danger')->visible(fn()=>$this->record->status==='PAID')->schema([Textarea::make('reason')->required()->minLength(20)])->action(function(array$d){if(ServiceValidation::run(fn()=>app(ClaimPaymentService::class)->reverse($this->record,$d['reason'],auth()->user()))===null)return;})];}}
